import { getSearchHistory, setSearchHistory, removeSearchHistory } from '@/utils/storage'

const state = () => {
  return {
    historyList: [
      {
        id: '1001',
        name: '小米15Pro'
      }
    ]
  }
}

const mutations = {
  appendHistoryList (state, obj) {
    state.historyList = state.historyList.filter((item) => {
      return item.name !== obj.name
    })
    state.historyList.unshift(obj)
    setSearchHistory(state.historyList)
  },
  setHistoryList (state) {
    const list = getSearchHistory()
    state.historyList = list
  },
  removeHistoryList (state) {
    state.historyList = []
    removeSearchHistory()
  }
}

export default {
  namespaced: true,
  state,
  mutations
}
