import { getUserInfo, setUserInfo } from '@/utils/storage'

const state = {
  // 刷新页面vuex里面的数据会丢失，那就让vuex刷新后去localstorage里面读数据
  // 获取本地存储中的userInfo信息，如果本地没有，在方法中也处理了，会返回{ token: null, userId: null }
  userInfo: getUserInfo()
}

const mutations = {
  // 所有mutations的第一个参数，都是state
  setUserInfo (status, obj) {
    // 设置vuex的数据
    status.userInfo = obj
    // 存入localStorage
    setUserInfo(obj)
  }
}

const actions = {
  logout (context) {
    context.commit('setUserInfo', {})
    // vuex跨模块访问
    context.commit('cart/setCartList', [], { root: true })
  }
}

export default {
  // 开启命名空间，与其他模块独立，才可以通过map('user',['xxx'])这样访问
  namespaced: true,
  state,
  mutations,
  actions
}
