import Layout from '@/views/layout'
import Home from '@/views/layout/home.vue'
import Cart from '@/views/layout/cart.vue'
import Category from '@/views/layout/category.vue'
import User from '@/views/layout/user.vue'
const Login = () => import(/* webpackChunkName: "group-login" */'@/views/login')
const MyOrder = () => import(/* webpackChunkName: "group-buy" */'@/views/myorder')
const Pay = () => import(/* webpackChunkName: "group-buy" */'@/views/pay')
const ProDetail = () => import(/* webpackChunkName: "group-proDetail" */'@/views/prodetail')
const Search = () => import(/* webpackChunkName: "group-search" */'@/views/search')
const SearchList = () => import(/* webpackChunkName: "group-search" */'@/views/search/searchList.vue')
const Address = () => import(/* webpackChunkName: "group-address" */'@/views/address')
const AddressEdit = () => import(/* webpackChunkName: "group-address" */'@/views/address/addressEdit.vue')

Vue.use(VueRouter)

const routes = [
  { path: '/login', component: Login },
  {
    path: '/',
    component: Layout,
    redirect: '/home',
    children: [
      { path: '/home', component: Home },
      { path: '/cart', component: Cart },
      { path: '/category', component: Category },
      { path: '/user', component: User }
    ]
  },
  { path: '/myorder', component: MyOrder },
  { path: '/pay', component: Pay },
  // 动态路由传参
  { path: '/prodetail', component: ProDetail },
  { path: '/search', component: Search },
  { path: '/searchList', component: SearchList },
  { path: '/address', component: Address },
  { path: '/addressEdit', component: AddressEdit }
]

const router = new VueRouter({
  routes
})

const authList = ['/pay', 'myOrder']

// 所有的路由在真正被访问到之前（解析渲染对应组件页面前），都会先经过全局前置守卫
// 当一个导航触发时，全局前置守卫按照创建顺序调用。
router.beforeEach((to, from, next) => {
  // console.log(to, from, next)
  // 非权限页面直接放行
  if (!authList.includes(to.path)) {
    next()
    return
  }
  // 不是store.user.state，先state在.user访问user命名空间里面的
  const token = store.state.user.userInfo.token
  // console.log(token)
  if (token) {
    next()
  } else {
    next('/login')
  }
})

export default router
