import axios from 'axios'
import { Toast } from 'vant'
import store from '@/store'

// 创建实例时配置默认值，好处：不会污染原始的axios实例
const instance = axios.create({
  baseURL: 'https://smart-shop.itheima.net/index.php?s=/api',
  timeout: 5000
})

// 创建实例后修改默认值
// instance.defaults.headers.common.Authorization = AUTH_TOKEN

// 添加请求拦截器
instance.interceptors.request.use(function (config) {
  // 在发送请求之前做些什么
  Toast.loading({
    message: '请求中...',
    forbidClick: true, // 禁用背景点击，同时实现了节流效果，请求没完成，用户点击不了
    duration: 0 // 不让toast自动关
  })

  const token = store.getters.token
  if (token) {
    config.headers['Access-Token'] = token
  }
  config.headers.platform = 'H5'

  return config
}, function (error) {
  // 对请求错误做些什么
  return Promise.reject(error)
})

// 添加响应拦截器
instance.interceptors.response.use(function (response) {
  // 2xx 范围内的状态码都会触发该函数,对响应数据做点什么，这里的状态码是最外层的状态码
  // 是response.status，不是response.data.status里面的,response.data.status里面的数据全是后端返回过来的

  const res = response.data
  const status = res.status
  if (status !== 200) {
    Toast.fail(res.message)
    // 返回一个拒绝的Promise，reject的Promise await及其后面的代码就不会执行了
    return Promise.reject(res.message)
  } else {
    Toast.clear()
  }

  // 去掉响应中的一层data，response.data中是后端返回来的全部数据，通常为一个JSON对象（RestController默认返回）
  // @ResponseBody用于将控制器的方法返回值直接写入 HTTP 响应体中，当需要向客户端返回 JSON 或 XML 格式的响应数据时，使
  // 用 @ResponseBody 可以方便地将 Java 对象转换为相应的格式。
  return response.data
}, function (error) {
  // 超出 2xx 范围的状态码都会触发该函数，对响应错误做点什么，这里的状态码是最外层的状态码

  return Promise.reject(error)
})

export default instance
