<template>
  <div id="home-box">

    <div class="header">
      <div class="title-box"><span class="title">智慧商城</span></div>
    </div>

    <div class="search">
      <van-search v-model="searchValue" shape="round" placeholder="请输入搜索关键词" @click="clickSearch"/>
    </div>

    <div class="swipper-box">
      <van-swipe class="my-swipe" indicator-color="white" autoplay="3000">
        <van-swipe-item v-for="(item,index) in bannerList" :key="index">
          <img :src="item.imgUrl" class="image" />
        </van-swipe-item>
      </van-swipe>
    </div>

    <div class="main">
      <img src="@/assets/images/main.png">
    </div>

    <div class="item-box">
      <div class="item" v-for="(item,index) in navBarList" :key="index">
        <van-icon :name="item.imgUrl" size="60px" />
        <span>{{item.text}}</span>
      </div>
    </div>

    <goods-item v-for="(item) in goodsList" :key="item.goods_id" :item="item"></goods-item>
  </div>
</template>

<script>
import GoodsItem from '@/components/GoodsItem.vue'
import { getHomeData } from '@/api/home'

export default {
  name: 'HomePage',
  data () {
    return {
      searchValue: '',
      bannerList: [],
      navBarList: [],
      goodsList: []
    }
  },
  methods: {
    clickSearch () {
      this.$router.push('/search')
    }
  },
  components: {
    GoodsItem
  },
  async created () {
    const response = await getHomeData()
    // console.log(response)
    const swipperMsg = response.data.pageData.items[1]
    const navBarMsg = response.data.pageData.items[3]
    const goodsMsg = response.data.pageData.items[6]

    this.bannerList = swipperMsg.data
    this.navBarList = navBarMsg.data
    this.goodsList = goodsMsg.data
  }
}
</script>

<style type="text/css" scoped lang="less">
#home-box {
  // 顶部的导航栏和搜索框固定，需要把这部分空间留出来，不然会有遮挡
  margin-top: 100px;
  // 底部的Tabbar固定，需要把底部的空间留出来
  margin-bottom: 50px;

  .header {
    width: 100%;
    position: fixed;
    top: 0;
    z-index: 999;

    .title-box {
      height: 40px;
      display: block;
      background-color: rgb(184, 0, 0);
      // 行内元素（inline）无法通过CSS 设置宽高，通过设置行高与父元素一直来实现垂直居中
      line-height: 40px;
      // 水平居中
      text-align: center;

      .title {
        color: white;
      }
    }
  }

  .search{
    position: fixed;
    top: 40px;
    width: 100%;
    z-index: 999;
  }

  .swipper-box {
    margin: 5px;
    height: 185px;
    display: flex;

    .image {
      width: 100%;
      height: 185px;
      object-fit: cover;
    }
  }

  .main {
    img {
      // 不用设置高度，让宽度沾满，高度则按图片比例来
      width: 100%;
    }
  }

  .item-box {
    display: flex;
    flex-direction: row;
    // .item-box 是一个 Flex 容器，其子元素 .item 默认情况下会按照 flex-direction: row（水平方向）排列，并且不会自动换行。
    // 如果你希望 .item 元素在容器空间不足时自动换行，可以通过设置 flex-wrap: wrap 来实现。
    flex-wrap: wrap;

    .item {
      display: flex;
      flex-direction: column;
      width: 70px;
      height: 80px;
      margin: 0 auto;
      text-align: center;
      align-items: center;

      span {
        font-size: 10px;
      }
    }
  }
}
</style>
