<template>
  <div id="category">

    <div class="header">
      <van-nav-bar title="分类页" fixed />
      <van-search shape="round" placeholder="请输入搜索关键词" @click="clickSearch" />
    </div>

    <div class="content" v-if="sidebarList">
      <div class="left">
        <van-sidebar v-model="activeKey">
          <van-sidebar-item v-for="item in sidebarList" :title="item.name" :key="item.category_id" />
        </van-sidebar>
      </div>
      <!-- 后端接口有些数据没有children属性，v-for里面用?.会报错，所以可以这样 -->
      <div class="right" v-if="sidebarList[activeKey]">
        <van-grid :column-num="3" icon_size="28px" >
          <van-grid-item v-for="item in sidebarList[activeKey].children" :key="item.category_id"
            :icon="item.image.external_url" :text="item.name"
            @click="clickItem(item.category_id)" />
        </van-grid>
      </div>
    </div>
  </div>
</template>

<script>
import { getCategory } from '@/api/category'
export default {
  name: 'CategoryPage',
  data () {
    return {
      activeKey: 0,
      sidebarList: []
    }
  },
  methods: {
    clickSearch () {
      this.$router.push('/search')
    },
    clickItem (id) {
      this.$router.push(`/searchList?id=${id}`)
    }
  },
  async created () {
    const response = await getCategory()
    console.log(response)
    this.sidebarList = response.data.list
  }
}
</script>

<style type="text/css" scoped lang="less">
#category {
  margin-top: 44px;

  .content {
    display: flex;
    flex-direction: row;
  }

  .left{
    display: flex;
  }

  .right {

    .van-grid-item {
      width: 100px;
      height: 90px;
    }

  }
}
</style>
