// import { getDefaultAddressId, getDetailByAddressId } from '@/api/address'

const state = () => {
  return {
    defaultAddressId: null,
    showAddressId: null
  }
}

const mutations = {
  setDefaultAddressId (state, id) {
    state.defaultAddressId = id
  },
  setShowAddressId (state, id) {
    state.showAddressId = id
  }
}

const actions = {
}

export default {
  namespaced: true,
  state,
  mutations,
  actions
}
