import request from '@/utils/requests'

export const addCart = (id, num, sku) => {
  return request({
    method: 'POST',
    url: '/cart/add',
    data: {
      goodsId: id,
      goodsNum: num,
      goodsSkuId: sku
    }
  })
}

export const getCart = () => {
  return request({
    method: 'GET',
    url: '/cart/list'
  })
}

export const changeCart = (goodsId, goodsNum) => {
  return request({
    method: 'POST',
    url: '/cart/update',
    data: {
      goodsId,
      goodsNum,
      goodsSkuId: '0'
    }
  })
}

export const deleteCart = (cartIds) => {
  // console.log('(后端)idsList', cartIds)
  return request({
    method: 'POST',
    url: '/cart/clear',
    data: {
      cartIds
    }
  })
}
