<template>
  <div id="countBox">
    <button @click="add(-1)">-</button>
    <input :value="value" type="text" @change="handleChange">
    <button @click="add(+1)">+</button>
  </div>
</template>

<script>
export default {
  name: 'CountBox',
  data () {
    return {}
  },
  methods: {
    add (number) {
      const num = Number(this.value) + number
      if (num < 1) {
        return
      }
      this.$emit('input', num)
    },
    handleChange (event) {
      // 无论输入框的 type 是 text 还是 number，JavaScript 中通过 event.target.value 获取的值始终是 字符串类型
      const num = event.target.value
      // 输入了不合法的文本或输入了负值，回退成原来的value值
      // isNaN(num)--> 当num是字符串"177"时，isNaN("177") 会先将"177"隐式转换为数字177，再判断是否为NaN。结果：isNaN(177) → false。
      if (isNaN(num) || num < 1) {
        event.target.value = this.value
        return
      }
      // this.$emit('input', num)
      // 这里一定要记得转换
      this.$emit('input', Number(num))
    }
  },
  props: {
    value: {
      require: true,
      type: Number,
      default: 1
    }
  }
}
</script>

<style type="text/css" scoped lang="less">
#countBox {
  z-index: 1;
  button {
    border-radius: 6px;
    width: 25px;
    border: 1px solid rgb(255, 255, 255);
    padding: 3px 0;
    margin: 0 4px;
  }

  input {
    max-width: 40px;
    border: 0;
    text-align: center;
    border-radius: 6px;
  }
}
</style>
