import { getCart, changeCart, deleteCart } from '@/api/cart'
import { Toast } from 'vant'

export default {
  namespaced: true,
  state () {
    return {
      cartList: []
    }
  },
  mutations: {
    setCartList (state, list) {
      state.cartList = list
      // console.log('state', state.cartList)
    },

    // 处理单选框点击，进行反选
    clickCheckBoxMutation (state, goodsId) {
      state.cartList.forEach((item) => {
        if (item.goods_id === goodsId) {
          item.isChecked = !item.isChecked
        }
      })
    },
    // 全选按钮点击处理
    clickSelectAllMutation (state, changeState) {
      state.cartList.forEach((item) => {
        item.isChecked = changeState
      })
    },
    // (vuex)修改商品数目
    changeCountMutation (state, { goodsId, count }) {
      state.cartList.forEach((item) => {
        if (item.goods_id === goodsId) {
          item.goods_num = count
        }
      })
    },
    // (vuex)删除商品
    deleteCartMutation (state, idsList) {
      console.log('(vuex)idsList', idsList)
      state.cartList = state.cartList.filter((item) => {
        return !idsList.includes(String(item.id))
      })
    }

  },
  actions: {
    // 从后端获取购物车数据
    async getCartAction (context) {
      const response = await getCart()
      // 后台返回的数据中，不包含复选框的选中状态，为了实现将来的功能
      // 需要手动维护数据，给每一项，添加一个 isChecked 状态（标记当前商品是否选中）
      const list = response.data.list
      list.forEach(item => {
        item.isChecked = true
      })
      context.commit('setCartList', list)
    },

    // 修改商品数目
    async changeCartAction (context, { goodsId, count }) {
      // 修改vuex中的本地数据，或者重新拉取购物车数据，（注意，一定要到删除请求完成后）
      context.commit('changeCountMutation', { goodsId, count })
      // 同步到后端
      const response = await changeCart(goodsId, count)
      console.log(response)
      Toast('修改成功')

      // 重新拉取购物车数据（自己维护数据有风险，全部重新拉后端的数据是最稳妥的，不然前后端数据不一致，是严重bug）
      // context.dispatch('getCartAction')
    },

    // 删除购物车商品
    async deleteCartAction (context) {
      // 这里必须存一下，要不然先本地vuex修改，在读取本地vuex，给后端的请求永远是空数组
      const idslist = context.getters.getSelectCartId
      // 本地删除，或者重新拉取购物车数据（注意，一定要到删除请求完成后）
      context.commit('deleteCartMutation', idslist)
      // 后端删除
      const response = await deleteCart(idslist)
      console.log(response)
      Toast('删除成功')

      // 或者重新拉取购物车数据
      // context.dispatch('getCartAction')
    }

  },
  getters: {
    // 商品总数
    getProTotal (state) {
      return state.cartList.reduce((sum, item) => {
        return sum + item.goods_num
      }, 0)
    },

    // 选中商品cartlist
    getSelectCartList (state) {
      return state.cartList.filter((item) => {
        return item.isChecked
      })
    },

    // 选中商品总数
    getSelectTotal (state, getters) {
      return getters.getSelectCartList.reduce((num, item) => {
        return num + item.goods_num
      }, 0)
    },

    // 选中商品总价格
    getSelectPrice (state, getters) {
      return getters.getSelectCartList.reduce((num, item) => {
        return num + item.goods_num * item.goods.goods_price_min
      }, 0).toFixed(2)
    },

    // 全选按钮状态
    isAllChecked (state) {
      // 灵活运用多种函数可以省很多事
      // return state.cartList.every(item => item.isChecked)

      // forEach 的回调函数中的return只会退出当前回调，但forEach会继续遍历下一个元素，无法终止外层函数
      // 即使发现 item.isChecked === false，外层函数仍会继续执行并返回 true。若强行用 forEach 实现，需借助外部变量。
      let flag = true
      state.cartList.forEach((item) => {
        if (item.isChecked === false) {
          flag = false
        }
      })
      return flag
    },

    // 选中商品的id集合
    getSelectCartId (state, getters) {
      const list = getters.getSelectCartList.map((item) => {
        return String(item.id)
        // return item.id // 后端要的数据就是String Array
      })
      // console.log('idslist', list)
      return list
    }
  }
}
