const INFO_KEY = 'hm_shopping_user'
const SEARCH_HISTORY_KEY = 'hm_search_history'

export const getUserInfo = () => {
  const defaultObj = { token: null, userId: null }
  const result = localStorage.getItem(INFO_KEY)
  return result ? JSON.parse(result) : defaultObj
}

export const setUserInfo = (obj) => {
  localStorage.setItem(INFO_KEY, JSON.stringify(obj))
}

export const delUserInfo = () => {
  localStorage.removeItem(INFO_KEY)
}

export const setSearchHistory = (obj) => {
  localStorage.setItem(SEARCH_HISTORY_KEY, JSON.stringify(obj))
}

export const getSearchHistory = () => {
  const defaultObj = []
  return JSON.parse(localStorage.getItem(SEARCH_HISTORY_KEY)) || defaultObj
}

export const removeSearchHistory = () => {
  localStorage.removeItem(SEARCH_HISTORY_KEY)
}
