<template>
  <div id="cart-box">

    <div class="header">
      <van-nav-bar title="购物车" fixed />
      <div>
        <span>共{{ getProTotal }}件商品</span>
        <button @click="clickEdit" v-if="isBuy"><van-icon name="edit" />编辑</button>
        <button @click="clickOver" v-else><van-icon name="revoke" />完成</button>
      </div>
    </div>

    <div v-if="isLogin && !isEmpty">
      <div>
        <div class="pro-item" v-for="(item) in cartList" :key="item.goods_id">
          <div class="left">
            <!-- <van-checkbox name="a" v-model="item.isChecked"></van-checkbox> -->
            <van-checkbox name="a" :value="item.isChecked" @click="clickCheckBox(item.goods_id)"></van-checkbox>
          </div>

          <div class="middle">
            <div class="img-box">
              <img :src="item.goods.goods_image">
            </div>
          </div>

          <div class="right">
            <div class="top">
              <span>{{ item.goods.goods_name }}</span>
            </div>
            <div class="bottom">
              <div class="buttom-left">
                <span>￥{{ item.goods.goods_price_min }}</span>
              </div>
              <div class="buttom-right">
                <!-- <CountBox v-model="item.goods_num"></CountBox> -->
                <!-- 不要直接使用v-model，这样会直接修改vuex的数据，虽然可以成功更改（应为修改的是vuex中对象的属性，而不是把vuex中整个对象替换掉）
              修改的是cartList[index].goods_num，为vuex中cartList中第一个元素中的一个属性-->
                <CountBox :value="item.goods_num" @input="changeCount(item.goods_id, $event)"></CountBox>
              </div>
            </div>
          </div>

        </div>
      </div>

      <div class="footer-fixed">
        <div class="all-check" @click="clickSelectAll(!isAllChecked)">
          <van-checkbox icon-size="18" v-bind:value="isAllChecked"></van-checkbox>
          全选
        </div>

        <div class="all-total">
          <div class="price">
            <span>合计：</span>
            <span>¥ <i class="totalPrice">{{ getSelectPrice }}</i></span>
          </div>
          <div v-if="isBuy" :class="{ disabled: getSelectTotal === 0 }" class="goPay" @click="goBuy">
            结算({{ getSelectTotal }})
          </div>
          <div v-else :class="{ disabled: getSelectTotal === 0 }" class="delete" @click="deleteCart">
            删除({{ getSelectTotal }})
          </div>
        </div>
      </div>
    </div>
    <div class="empty-cart" v-else>
      <img src="@/assets/images/empty.png" alt="">
      <div class="tips">
        您的购物车是空的, 快去逛逛吧
      </div>
      <div class="btn" @click="$router.push('/')">去逛逛</div>
    </div>
  </div>
</template>

<script>
import CountBox from '@/components/CountBox.vue'
import { mapActions, mapGetters, mapMutations, mapState } from 'vuex'
export default {
  name: 'CartPage',
  data () {
    return {
      result: [],
      isBuy: true
    }
  },
  computed: {
    ...mapState('cart', ['cartList']),
    ...mapGetters('cart', ['getProTotal', 'getSelectTotal', 'getSelectPrice', 'getSelectCartList', 'isAllChecked']),
    isEmpty () {
      if (this.cartList.length === 0) {
        return true
      }
      return false
    },
    isLogin () {
      if (this.$store.getters.token) {
        return true
      } else {
        return false
      }
    }
  },
  methods: {
    ...mapActions('cart', ['getCartAction', 'changeCartAction', 'deleteCartAction']),
    ...mapMutations('cart', ['clickCheckBoxMutation', 'clickSelectAllMutation']),
    // 单选按钮
    clickCheckBox (goodsId) {
      this.clickCheckBoxMutation(goodsId)
    },
    // 全选按钮
    clickSelectAll (changeState) {
      this.clickSelectAllMutation(changeState)
    },
    // 编辑按钮
    clickEdit () {
      this.isBuy = false
      // 点击编辑按钮把选中状态全部设为未选中
      this.clickSelectAll(false)
    },
    // 完成按钮
    clickOver () {
      this.isBuy = true
      // 点击完成按钮把选中状态全部设为选中
      this.clickSelectAll(true)
    },
    // 修改商品数目
    changeCount (goodsId, count) {
      this.changeCartAction({ goodsId, count })
    },
    // 删除购物车商品
    deleteCart () {
      if (this.getSelectTotal <= 0) {
        return
      }
      this.deleteCartAction()
    },
    // 去购买
    goBuy () {
      if (this.getSelectTotal <= 0) {
        return
      }
      this.$router.push({
        path: '/pay',
        query: {
          mode: 'cart',
          cartIds: this.getSelectCartList.map((item) => {
            return item.id
          }).join(',')
        }
      })
    }
  },
  components: {
    CountBox
  },
  created () {
    if (this.$store.getters.token) {
      this.getCartAction()
    }
  }

}
</script>

<style scoped lang="less">
#cart-box {
  margin-top: 76px;
  margin-bottom: 100px;

  .header {
    position: fixed;
    top: 46px;
    width: 100%;
    background-color: white;
    z-index: 999;
    height: 30px;

    button {
      position: fixed;
      right: 10px;
      border: 0;
      background-color: white;
    }
  }

  .pro-item {
    display: flex;
    flex-direction: row;
    width: 100%;
    height: 150px;
    margin: 5px 0;
    background-color: rgb(250, 250, 250);
    z-index: 1;

    .left {
      width: 20px;
      margin: auto 0 auto 10px;
    }

    .middle {
      .img-box {
        height: 140px;
        width: 140px;
        padding: 6px;
      }

      img {
        width: 100%;
        border-radius: 4px;
        overflow: hidden;
      }
    }

    .right {
      padding: 10px 0;
      display: flex;
      flex-direction: column;

      .top {
        min-height: 100px;
      }

      .bottom {
        height: 30px;
        display: flex;
        flex-direction: row;

        .buttom-left {
          display: inline-block;
          width: 90px;

          span {
            color: rgb(186, 36, 36);
          }
        }

        .bottom-right {
          display: inline-block;
        }
      }
    }
  }

  .footer-fixed {
    position: fixed;
    left: 0;
    bottom: 50px;
    height: 50px;
    width: 100%;
    border-bottom: 1px solid #ccc;
    background-color: #fff;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 10px;

    .all-check {
      display: flex;
      align-items: center;

      .van-checkbox {
        margin-right: 5px;
      }
    }

    .all-total {
      display: flex;
      line-height: 36px;

      .price {
        font-size: 14px;
        margin-right: 10px;

        .totalPrice {
          color: #fa2209;
          font-size: 18px;
          font-style: normal;
        }
      }

      .goPay,
      .delete {
        min-width: 100px;
        height: 36px;
        line-height: 36px;
        text-align: center;
        color: #fff;
        border-radius: 18px;

      }

      .goPay {
        background-color: #fa2f21;

        &.disabled {
          background-color: #ff9779;
        }
      }

      .delete {
        background-color: #323232;

        &.disabled {
          background-color: #898989;
        }
      }
    }
  }

  .empty-cart {
    padding: 80px 30px;

    img {
      width: 140px;
      height: 92px;
      display: block;
      margin: 0 auto;
    }

    .tips {
      text-align: center;
      color: #666;
      margin: 30px;
    }

    .btn {
      width: 110px;
      height: 32px;
      line-height: 32px;
      text-align: center;
      background-color: #fa2c20;
      border-radius: 16px;
      color: #fff;
      display: block;
      margin: 0 auto;
    }
  }
}
</style>
